mapper.select:
SELECT model_code, version, label, upstream_model_name FROM dm_ai_model_config WHERE provider_code IN
#{code}
ORDER BY label, model_code

mapper.update:
UPDATE
    dm_ai_model_config
SET
    verification_status = #{status},
    verified_version    = #{version},
    verified_at         = #{verifiedAt}
WHERE
    model_code = #{code}
    AND
    version    = #{version}

mapper.delete:
DELETE FROM
    dm_ai_model_config
WHERE
    model_code = #{code}
    AND
    version    = #{version}
